window.kbPageData["views/entry/k-10c78f5272e0889f"] = {"key":"entry/k-10c78f5272e0889f","state":{"route":"entry/k-10c78f5272e0889f"},"node":{"id":"k-10c78f5272e0889f","mode":"k","title":"固定年增量下的规模推算","type":"原理与机制","domain":"统计","reading":"","intro":"","priority":100,"aliases":["固定年增量下未来规模等于起始规模加上年数乘年增量","固定年增量下未来规模等于基准规模加预测年数乘以年增量"],"qs":["国考 2023 副省级 行测#129","国考 2023 地市级 行测#119"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":2,"repeatPositions":0,"directorySummary":"如果某项规模每年增加的数额相同，那么经过 n 年后的规模等于起始年份的规模加上 n 倍的年增量。","review":{"definition":"如果某项规模每年增加的数额相同，那么经过 n 年后的规模等于起始年份的规模加上 n 倍的年增量。","explanation":"以2021年为起点，第三方互联网超算服务商的市场规模为13.8亿元，比第三方独立超算服务商的18.3亿元少4.5亿元。按2021年的同比增量推算，两者每年分别增加4.3亿元和3.3亿元，差距每年缩小1亿元。题干要求首次严格超过，因此经过的整年数 n 须满足 n＞4.5，最早为2026年，对应B项。","references":[],"evidence":"现期量=基期量+n×增长量","disposition":"独立词条","basis":"据原题和解析编释。","title":"固定年增量下的规模推算","related":[],"examFocus":{"国考 2023 副省级 行测#129":"以2021年为起点，按两类超算服务商各自的同比增量推算，比较两者市场规模何时首次出现严格反超。","国考 2023 地市级 行测#119":"根据两类超算服务商2021年的市场规模和各自的同比增量，按固定年增量推算并比较两者的规模。"}},"readings":[{"origin":"k-10c78f5272e0889f","title":"固定年增量下的规模推算","qs":["国考 2023 副省级 行测#129"],"definition":"如果某项规模每年增加的数额相同，那么经过 n 年后的规模等于起始年份的规模加上 n 倍的年增量。","explanation":"以2021年为起点，第三方互联网超算服务商的市场规模为13.8亿元，比第三方独立超算服务商的18.3亿元少4.5亿元。按2021年的同比增量推算，两者每年分别增加4.3亿元和3.3亿元，差距每年缩小1亿元。题干要求首次严格超过，因此经过的整年数 n 须满足 n＞4.5，最早为2026年，对应B项。","evidence":"现期量=基期量+n×增长量","doubt":"","references":[]},{"origin":"k-6ba1fcd95cf4cf83","title":"固定年增量下的规模推算","qs":["国考 2023 地市级 行测#119"],"definition":"当某项规模每年增加的数额相同时，基准年之后第 n 年的规模等于基准年规模加上 n 倍的年增量，其中 n 为自基准年起经过的整年数。","explanation":"本题以2021年为基准。按解析所列数据，第三方互联网超算服务商和第三方独立超算服务商的市场规模分别为13.8亿元和18.3亿元，2021年同比增量分别为4.3亿元和3.3亿元。若各自保持该年增量，前者每年缩小1亿元差距。首次超过要求累计缩小的差距严格大于初始差距4.5亿元，因此最少经过5年，即2026年，选B。","evidence":"现期量=基期量+n×增长量","doubt":"","references":[]}]},"questions":{"国考 2023 副省级 行测#129":{"paper":"国考 2023 副省级 行测","n":129,"mod":"资料分析","src":["503793642e845de9795f.pdf",27],"asrc":["ecade1ff5af69283232e.pdf",40],"card":"2f8e6fe13043622706f0f91a","links":[{"id":"k-10c78f5272e0889f","role":"解题依据","why":"按各自固定的增量表示两类服务商若干年后的规模。"}]},"国考 2023 地市级 行测#119":{"paper":"国考 2023 地市级 行测","n":119,"mod":"资料分析","src":["64bc3a15d27a04e94940.pdf",24],"asrc":["f3ab652d8e31c5bbdabc.pdf",39],"card":"515dfc003022da7cd11aa1e3","links":[{"id":"k-10c78f5272e0889f","role":"解题依据","why":"以2021年规模为基准推算两类服务商在同一未来年份的规模。"}]}},"terms":{},"references":{},"topics":[],"units":{"k-10c78f5272e0889f":[["国考 2023 副省级 行测#129"],["国考 2023 地市级 行测#119"]]}};
